import os
from urllib.parse import unquote

BASE = "/srv/files"

def resolve(raw):
    path = unquote(raw)                      # decode exactly once
    full = os.path.normpath(os.path.join(BASE, path))
    if os.path.commonpath([BASE, full]) != BASE:
        raise ValueError("outside " + BASE)
    return full                              # check and use the same value

for p in ["report.pdf", "../etc/passwd", "%2e%2e/etc/passwd"]:
    try:
        print("ALLOWED", resolve(p))
    except ValueError as e:
        print("BLOCKED", p, "->", e)

def lenient_decode(data):
    """Toy decoder: handles 1- and 2-byte forms, never checks for overlongs."""
    out, i = [], 0
    while i < len(data):
        b = data[i]
        if b < 0x80:
            out.append(chr(b)); i += 1
        elif b >> 5 == 0b110:                      # 110xxxxx 10xxxxxx
            cp = ((b & 0x1F) << 6) | (data[i + 1] & 0x3F)
            out.append(chr(cp)); i += 2
        else:
            raise ValueError("unsupported byte")
    return "".join(out)

