import html
from urllib.parse import urlsplit

def safe_href(value):
    """value is the user's URL as plain text, never pre-encoded HTML."""
    u = urlsplit(value)          # Python also drops tab/newline and leading C0
    if u.scheme not in ("http", "https") or not u.hostname:
        raise ValueError("scheme not allowed: " + repr(u.scheme))
    return '<a href="' + html.escape(value, quote=True) + '">link</a>'

