from unicodedata import normalize

USERS = ["admin@corp.example", "ana@corp.example"]

def reset_bad(submitted):
    for stored in USERS:                       # like UPPER(email) = UPPER(%s)
        if stored.upper() == submitted.upper():
            return f"token for {stored} mailed to {submitted}"
    return "no account"

def ci(s):                                     # UTR 36: NFKC then case fold
    return normalize("NFKC", s).casefold()

def reset_good(submitted):
    for stored in USERS:
        if stored.upper() == submitted.upper() and ci(stored) == ci(submitted):
            return f"token for {stored} mailed to {stored}"
    return "no account"

attempt = "admın@corp.example"           # dotless i (U+0131)
print(reset_bad(attempt))
print(reset_good(attempt))
print(reset_good("ADMIN@corp.example"))

# Toy model of a lossy "best-fit" conversion to a legacy code page.
# Real tables are per code page; these three entries follow DEVCORE's write-ups.
BEST_FIT = {"\u00ad": "-",  # soft hyphen to hyphen-minus (cp932/936/950)
            "¥": "\\",    # yen sign to backslash (cp932)
            "／": "/"}     # fullwidth solidus to solidus

def to_ansi(text):
    return "".join(BEST_FIT.get(c, c if ord(c) < 128 else "?") for c in text)

def launch_bad(arg):
    if arg.startswith("-"):              # check on the wide (UTF-16) string
        raise ValueError("options not allowed")
    return ["tool.exe", to_ansi(arg)]     # the child reads the ANSI copy

def launch_good(arg):
    narrow = to_ansi(arg)                # convert first, then check what the child sees
    if narrow != arg or narrow.startswith("-"):
        raise ValueError("refused: conversion changed the argument")
    return ["tool.exe", narrow]

arg = "\u00adv"                      # soft hyphen + v
print(launch_bad(arg))
try:
    launch_good(arg)
except ValueError as e:
    print(e)

import unicodedata

def load(path="confusables.txt"):
    table = {}
    for line in open(path, encoding="utf-8-sig"):
        line = line.split("#", 1)[0].strip()
        if line:
            src, dst, _ = [f.strip() for f in line.split(";")]
            table[chr(int(src, 16))] = "".join(chr(int(h, 16)) for h in dst.split())
    return table

TABLE = load()

def skeleton(s):
    """UTS #39 internalSkeleton, minus the default-ignorable removal step."""
    s = unicodedata.normalize("NFD", s)
    s = "".join(TABLE.get(c, c) for c in s)
    return unicodedata.normalize("NFD", s)

