import pathlib, sys, unicodedata

SUSPECT = {0x202A, 0x202B, 0x202C, 0x202D, 0x202E,     # embeddings, overrides, PDF
           0x2066, 0x2067, 0x2068, 0x2069,             # isolates
           0x2028, 0x2029}                             # line/paragraph separator

def scan(root):
    hits = 0
    for path in sorted(pathlib.Path(root).rglob("*")):
        if not path.is_file():
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        for lineno, line in enumerate(text.splitlines(keepends=True), 1):
            for col, ch in enumerate(line, 1):
                if ord(ch) in SUSPECT:
                    hits += 1
                    print(f"{path}:{lineno}:{col}: U+{ord(ch):04X} {unicodedata.name(ch)}")
    return hits

sys.exit(1 if scan(sys.argv[1]) else 0)

