def no_dupes(pairs):
    keys = [k for k, _ in pairs]
    dupes = {k for k in keys if keys.count(k) > 1}
    if dupes:
        raise ValueError(f"duplicate keys: {sorted(dupes)}")
    return dict(pairs)

try:
    json.loads(doc, object_pairs_hook=no_dupes)
except ValueError as e:
    print("strict parser:", e)
