import re

BODY = ("--b1\r\n"
        'Content-Disposition: form-data; name="amount"\r\n\r\n'
        "10\r\n"
        "--b1\r\n"
        'Content-Disposition: form-data; name="amount"\r\n\r\n'
        "10000\r\n"
        "--b1--\r\n")

def parts(body, boundary):
    for chunk in body.split("--" + boundary)[1:-1]:
        head, _, value = chunk.strip("\r\n").partition("\r\n\r\n")
        yield re.search(r'name="([^"]*)"', head).group(1), value

def parse_first(body):                 # e.g. a fraud check
    out = {}
    for k, v in parts(body, "b1"):
        out.setdefault(k, v)
    return out

def parse_last(body):                  # e.g. the payment handler
    return dict(parts(body, "b1"))

def parse_strict(body):
    out = {}
    for k, v in parts(body, "b1"):
        if k in out:
            raise ValueError("duplicate field " + k)
        out[k] = v
    return out

print(parse_first(BODY)["amount"], parse_last(BODY)["amount"])
try:
    parse_strict(BODY)
except ValueError as e:
    print(e)
